uniform sampler2D map; uniform vec3 sunDir; uniform float uFlat; uniform float uZone; uniform float uMix; uniform float uSolo;
      uniform vec3 zT; uniform vec3 zW; uniform vec3 zC; uniform float trop; uniform float polar;
      varying vec2 vUv; varying vec3 vN; varying vec3 vV;
      void main(){
        vec3 t = texture2D(map, vUv).rgb;
        float lum = dot(t, vec3(0.2126, 0.7152, 0.0722));
        if (uSolo > 0.5) { t = vec3(0.3); lum = 0.3; }
        if (uMix > 0.999) lum = 0.3;                                         // Cong tac zone-cover: dai mau phu kin ban do nen
        float lit = smoothstep(-0.04, 0.22, dot(normalize(vN), sunDir));      // Chuyen tiep nhanh quanh duong phan chia sang - toi
        float k = mix(0.34 + 0.74 * lit, 1.0, uFlat);                         // Ban cau dem giam xuong khoang 1/3, van nhan ra luc dia
        float la = abs((vUv.y - 0.5) * 180.0);
        vec3 zc = la <= trop ? zT : (la < polar ? zW : zC);
        float sea = smoothstep(0.03, 0.14, t.b - max(t.r, t.g));            // Mat bien: kenh xanh lam cao ro ret
        if (uMix > 0.999) sea = 0.5;                                          // Cong tac zone-cover: khong phan biet dat va bien
        vec3 tinted = zc * mix(0.80, 1.06, sea) * (0.86 + 0.30 * lum);       // To mau phang + luc dia dam hon mot chut
        vec3 c = mix(t, tinted, uZone * uMix) * k;
        // Chi them o cac buoc co anh sang: chuyen tiep am quanh duong sang toi, phan xa Mat Troi tren bien ban ngay, vien khi quyen xanh nhat
        float ld = (1.0 - uFlat) * (1.0 - uZone);
        vec3 n = normalize(vN), v = normalize(vV);
        float dusk = lit * (1.0 - lit) * 4.0;
        c += ld * dusk * vec3(0.16, 0.06, -0.02);
        float glint = pow(max(dot(reflect(-sunDir, n), v), 0.0), 60.0) * sea * lit;
        c += ld * glint * vec3(0.55, 0.5, 0.42);
        float rim = pow(1.0 - max(dot(n, v), 0.0), 3.0);
        c = mix(c, vec3(0.62, 0.80, 1.0), ld * rim * (0.15 + 0.45 * lit));
        gl_FragColor = vec4(c, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
